1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	import net.officefloor.plugin.variable.Val;
9	import org.springframework.samples.petclinic.model.Owner;
10	
11	/**
12	 * Assigns the owner's deterministic {@code householdId}: the first 12 (upper-case) hex characters of
13	 * the SHA-256 of {@code normalizedLastName + '|' + postcode}. The id is derived purely from the
14	 * (lastName, postcode) pair, so every owner with the same lastName and postcode receives the same
15	 * value automatically, regardless of creation order and without any repository lookup or opt-in.
16	 *
17	 * <p>Because the household is now keyed on (lastName, postcode), owners sharing that pair are the
18	 * same household. This computed id is the single source of truth the household consumers key off
19	 * (see {@link HouseholdMembers}): {@link DeriveOwnerHouseholdSize}, {@link CapOwnerMembershipLevel}
20	 * (the membership-level ceiling) and {@link DetectOwnerPossibleDuplicate}. The request's
21	 * {@code sharesHousehold} flag no longer creates the link — the link is implicit in the shared id —
22	 * it only suppresses the possible-duplicate flag for a declared member
23	 * (see {@link DetectOwnerPossibleDuplicate}).
24	 *
25	 * <p>Runs after {@link BuildOwner} has created the entity and before the household consumers (which
26	 * see the resolved {@code householdId}) and {@link SaveOwner} persists it.
27	 */
28	public class AssignOwnerHousehold {
29	
30	    public void service(@Val Owner owner) {
31	        owner.setHouseholdId(householdId(owner.getLastName(), owner.getPostcode()));
32	    }
33	
34	    /**
35	     * The single source of truth for an owner's household identity: the first 12 upper-case hex
36	     * characters of the SHA-256 of {@code normalize(lastName) + '|' + postcode}. An absent postcode
37	     * contributes an empty segment. Two owners share a household exactly when this value is equal.
38	     */
39	    static String householdId(String lastName, String postcode) {
40	        String input = normalize(lastName) + "|" + (postcode == null ? "" : postcode);
41	        try {
42	            byte[] digest = MessageDigest.getInstance("SHA-256")
43	                    .digest(input.getBytes(StandardCharsets.UTF_8));
44	            StringBuilder sb = new StringBuilder(12);
45	            for (int i = 0; i < 6; i++) {
46	                sb.append(String.format("%02x", digest[i]));
47	            }
48	            return sb.toString().toUpperCase(Locale.ROOT);
49	        }
50	        catch (NoSuchAlgorithmException ex) {
51	            throw new IllegalStateException("SHA-256 not available", ex);
52	        }
53	    }
54	
55	    /** Lower-cased, trimmed, with internal whitespace runs collapsed to a single space. */
56	    static String normalize(String value) {
57	        if (value == null) {
58	            return "";
59	        }
60	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
61	    }
62	}
