4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * Flags the new owner as a possible (soft) duplicate, keyed off the computed
10	 * {@link Owner#getHouseholdId() householdId}: an owner is a possible duplicate when an earlier owner
11	 * shares its household (same lastName and postcode).
12	 *
13	 * <p>A <em>declared</em> household member — one created with {@code sharesHousehold} true — is never
14	 * flagged: it deliberately joins the household, so it is not a suspected duplicate. Any other owner
15	 * joining an existing household is allowed (its membership level is capped by
16	 * {@link CapOwnerMembershipLevel}) but flagged here as a possible duplicate, keying the soft signal
17	 * off the same {@link HouseholdMembers household membership} as the size and cap steps.
18	 *
19	 * <p>Runs after {@link BuildOwner}/{@link AssignOwnerHousehold} and before {@link SaveOwner},
20	 * scanning only pre-existing (already persisted) owners — the new owner has no id yet and is skipped.
21	 * The earliest such match (lowest id) is recorded: {@code possibleDuplicate} is set true and
22	 * {@code possibleDuplicateOf} to that owner's id; otherwise {@code possibleDuplicate} is false and
23	 * {@code possibleDuplicateOf} is left null. Both are stored on the built owner so the saved and
24	 * returned record carries them.
25	 */
26	public class DetectOwnerPossibleDuplicate {
27	
28	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
29	        Owner match = null;
30	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
31	            for (Owner member : HouseholdMembers.of(owner, ownerRepository)) {
32	                if (member.getId() == null) {
33	                    continue; // an unsaved member has no id to record as possibleDuplicateOf
34	                }
35	                if (match == null || member.getId() < match.getId()) {
36	                    match = member;
37	                }
38	            }
39	        }
40	        if (match != null) {
41	            owner.setPossibleDuplicate(true);
42	            owner.setPossibleDuplicateOf(match.getId());
43	        }
44	        else {
45	            owner.setPossibleDuplicate(false);
46	            owner.setPossibleDuplicateOf(null);
47	        }
48	    }
49	}
