3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * The single definition of "household member" shared by the steps that reason over a household:
11	 * {@link DeriveOwnerHouseholdSize}, {@link CapOwnerMembershipLevel} and
12	 * {@link DetectOwnerPossibleDuplicate}. A member is any <em>other</em> non-deleted owner that shares
13	 * the given owner's {@link Owner#getHouseholdId() householdId}. Keeping the self-exclusion and
14	 * soft-delete rules in one place ensures the consumers stay in lockstep rather than re-encoding the
15	 * filters independently.
16	 */
17	final class HouseholdMembers {
18	
19	    private HouseholdMembers() {
20	    }
21	
22	    /**
23	     * The non-deleted owners, other than {@code owner} itself, that share its
24	     * {@link Owner#getHouseholdId() householdId}. Empty when the owner has no household id. The owner
25	     * itself is excluded by id, so the result is correct in the create pipeline (where the owner may
26	     * not yet be persisted and so never appears in {@link OwnerRepository#findAll()}) as well as on
27	     * reads.
28	     */
29	    static List<Owner> of(Owner owner, OwnerRepository ownerRepository) {
30	        String householdId = owner.getHouseholdId();
31	        if (householdId == null) {
32	            return List.of();
33	        }
34	        List<Owner> members = new ArrayList<>();
35	        for (Owner existing : ownerRepository.findAll()) {
36	            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
37	                continue; // the owner itself is not one of its household members
38	            }
39	            if (existing.isDeleted()) {
40	                continue; // soft-deleted owners are not household members
41	            }
42	            if (householdId.equals(existing.getHouseholdId())) {
43	                members.add(existing);
44	            }
45	        }
46	        return members;
47	    }
48	}
