2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
6	
7	/**
8	 * Normalizes the owner's telephone on create into E.164 form, mutating the validated request in
9	 * place so later steps store and return the E.164 value. Spaces, dashes and brackets are stripped.
10	 * A leading '+' and its country code are kept as given; otherwise country code '+61' is assumed and
11	 * a single leading '0' is dropped from the national digits (so {@code 0412 345 678} becomes
12	 * {@code +61412345678}). The result must carry 8 to 15 digits after the '+', and its national
13	 * number (the digits after the country code) must match the length that country requires — '+61'
14	 * needs 9 national digits, '+1' needs 10. Anything that cannot form valid E.164 is rejected 400 via
15	 * {@link InvalidTelephoneException}.
16	 */
17	public class NormalizeOwnerTelephone {
18	
19	    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
20	        request.setTelephone(toE164(request.getTelephone()));
21	    }
22	
23	    /**
24	     * The single source of truth for what "same telephone" means: converts a raw telephone into its
25	     * E.164 form. Spaces, dashes and brackets are removed; a leading '+' and country code are kept,
26	     * otherwise '+61' is assumed and a single leading '0' is dropped from the national digits. The
27	     * digits after the '+' must number 8 to 15, no other characters may remain, and the national
28	     * number must have the length the country code requires ('+61' => 9, '+1' => 10). The E.164 value
29	     * is what is stored and returned; it also composes the display-only
30	     * {@link org.springframework.samples.petclinic.model.Owner#getIdentityKey() identityKey} but no
31	     * longer participates in duplicate detection (which is household-based).
32	     *
33	     * @throws InvalidTelephoneException if the value cannot form valid E.164.
34	     */
35	    static String toE164(String telephone) throws InvalidTelephoneException {
36	        if (telephone == null) {
37	            throw invalid();
38	        }
39	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
40	        String digits;
41	        if (cleaned.startsWith("+")) {
42	            digits = cleaned.substring(1);
43	        }
44	        else {
45	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
46	            digits = "61" + national;
47	        }
48	        if (!digits.matches("\\d{8,15}")) {
49	            throw invalid();
50	        }
51	        checkNationalLength(digits);
52	        return "+" + digits;
53	    }
54	
55	    /**
56	     * Rejects a number whose national number (the digits after the country code) does not match the
57	     * length that country code requires: '+61' => 9 national digits, '+1' => 10. Country codes not
58	     * listed here are left to the generic 8-to-15 digit rule.
59	     */
60	    private static void checkNationalLength(String digits) throws InvalidTelephoneException {
61	        String countryCode;
62	        int requiredNationalLength;
63	        if (digits.startsWith("61")) {
64	            countryCode = "61";
65	            requiredNationalLength = 9;
66	        }
67	        else if (digits.startsWith("1")) {
68	            countryCode = "1";
69	            requiredNationalLength = 10;
70	        }
71	        else {
72	            return;
73	        }
74	        int nationalLength = digits.length() - countryCode.length();
75	        if (nationalLength != requiredNationalLength) {
76	            throw new InvalidTelephoneException("Telephone with country code '+" + countryCode
77	                    + "' must have " + requiredNationalLength + " national digits, but had "
78	                    + nationalLength);
79	        }
80	    }
81	
82	    private static InvalidTelephoneException invalid() {
83	        return new InvalidTelephoneException(
84	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
85	    }
86	}
