9	/**
10	 * Derives the owner's {@code membershipLevelCap}: a new owner's {@code membershipLevel} cannot exceed
11	 * one above the current maximum {@code membershipLevel} among their household members (the other
12	 * owners sharing this owner's {@link Owner#getHouseholdId() householdId}, per {@link HouseholdMembers}).
13	 * The cap is one above that maximum; {@link Owner#getMembershipLevel()} applies it. When the owner has
14	 * no household id or no existing household member, no cap applies and the level stands unchanged.
15	 *
16	 * <p>The cap is a transient, response-time value set on the in-flight owner; it is not persisted.
17	 * Wired into the create pipeline (after {@link AssignOwnerHousehold} has stamped the shared id) and
18	 * the single-owner GET pipeline, so reads apply the same ceiling.
19	 */
20	public class CapOwnerMembershipLevel {
21	
22	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
23	        List<Owner> members = HouseholdMembers.of(owner, ownerRepository);
24	        if (members.isEmpty()) {
25	            return;
26	        }
27	        int maxMemberLevel = members.stream().mapToInt(Owner::getMembershipLevel).max().getAsInt();
28	        owner.setMembershipLevelCap(maxMemberLevel + 1);
29	    }
30	}
