1	package org.springframework.samples.petclinic.rest.function.common;
2	
3	import java.util.concurrent.ConcurrentHashMap;
4	import java.util.concurrent.ConcurrentMap;
5	
6	import org.springframework.stereotype.Component;
7	
8	/**
9	 * Remembers the owner created for each {@code Idempotency-Key} seen on {@code POST /api/owners},
10	 * so a repeated create with an already-seen key returns the originally created owner instead of
11	 * creating a duplicate.
12	 *
13	 * <p>A process-wide, in-memory map: the mapping is deliberately kept outside the request's
14	 * transaction so that once the first create commits its key, a retry finds it even though each
15	 * request is its own transaction. {@link #remember(String, Integer)} keeps the first id stored
16	 * for a key ({@code putIfAbsent}), so the returned owner is always the one originally created.
17	 */
18	@Component
19	public class IdempotencyStore {
20	
21	    private final ConcurrentMap<String, Integer> ownerIdByKey = new ConcurrentHashMap<>();
22	
23	    /** The owner id originally created for {@code key}, or {@code null} if the key is new. */
24	    public Integer find(String key) {
25	        return key == null ? null : ownerIdByKey.get(key);
26	    }
27	
28	    /** Record the owner created for {@code key}, keeping the first id if the key is already known. */
29	    public void remember(String key, Integer ownerId) {
30	        if (key != null && ownerId != null) {
31	            ownerIdByKey.putIfAbsent(key, ownerId);
32	        }
33	    }
34	}
