2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.repository.OwnerRepository;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	import org.springframework.samples.petclinic.rest.escalation.CityOwnerLimitExceededException;
7	
8	/**
9	 * Rejects creating an owner when the owner's city already holds {@value #CITY_CAPACITY} or more
10	 * owners. A city at capacity is rejected 409 via {@link CityOwnerLimitExceededException}.
11	 */
12	public class CheckOwnerCityCapacity {
13	
14	    static final int CITY_CAPACITY = 50;
15	
16	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
17	            throws CityOwnerLimitExceededException {
18	        String city = request.getCity();
19	        if (countInCity(ownerRepository, city) >= CITY_CAPACITY) {
20	            throw new CityOwnerLimitExceededException(
21	                    "City " + city + " already has " + CITY_CAPACITY + " or more owners");
22	        }
23	    }
24	
25	    /** Existing owners whose city equals {@code city} case-insensitively, backing the 409 gate. */
26	    private static long countInCity(OwnerRepository ownerRepository, String city) {
27	        return ownerRepository.findAll().stream()
28	                .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
29	                .count();
30	    }
31	}
