3	import net.officefloor.plugin.section.clazz.Flow;
4	import org.springframework.samples.petclinic.rest.function.common.IdempotencyStore;
5	import org.springframework.web.bind.annotation.RequestHeader;
6	
7	/**
8	 * The entry step of {@code POST /api/owners}: honours an optional {@code Idempotency-Key} header.
9	 *
10	 * <p>When the request carries a key already seen (a repeated create), the branch short-circuits to
11	 * {@code existing}, which loads and returns the owner originally created for that key with 200 —
12	 * no duplicate is created. Otherwise (no key, or a new key) the {@code create} branch runs the
13	 * normal validate-through-respond pipeline; the key, if any, is recorded once the owner is saved by
14	 * {@link RecordOwnerIdempotency}.
15	 *
16	 * <p>This runs before {@link ValidateOwner} reads the body, so a duplicate retry never binds
17	 * {@code @RequestBody} — only the taken branch does.
18	 */
19	public class CheckOwnerIdempotency {
20	
21	    @FunctionalInterface
22	    public interface ExistingOwnerFlow {
23	        void flow(Integer ownerId);
24	    }
25	
26	    @FunctionalInterface
27	    public interface CreateOwnerFlow {
28	        void flow();
29	    }
30	
31	    public void service(@RequestHeader(name = "Idempotency-Key", required = false) String idempotencyKey,
32	            IdempotencyStore idempotencyStore, @Flow("existing") ExistingOwnerFlow existing,
33	            @Flow("create") CreateOwnerFlow create) {
34	        Integer existingOwnerId = idempotencyStore.find(idempotencyKey);
35	        if (existingOwnerId != null) {
36	            existing.flow(existingOwnerId);
37	            return;
38	        }
39	        create.flow();
40	    }
41	}
