324	    /**
325	     * The ceiling applied to {@link #getMembershipLevel() membershipLevel}: one above the current
326	     * maximum membershipLevel among this owner's existing household members. Derived at response
327	     * time and not persisted; {@code null} means no household member exists and no cap applies.
328	     */
329	    public Integer getMembershipLevelCap() {
330	        return this.membershipLevelCap;
331	    }
