337	    /**
338	     * The owner's membership points, derived at response time. Starts at {@code 0}, plus 2 when an
339	     * email is present, plus 1 when {@link #namesakeCount} is 0, plus 2 when the
340	     * {@link #getHouseholdSize() household} has 3 or more members, plus 3 when tenure exceeds one
341	     * elapsed fiscal year (measured from the {@link #registrationDate}; see
342	     * {@link #getTenureFiscalYears()}).
343	     */
344	    public Integer getMembershipPoints() {
345	        int points = 0;
346	        if (this.email != null && !this.email.isEmpty()) {
347	            points += 2;
348	        }
349	        if (this.namesakeCount != null && this.namesakeCount == 0) {
350	            points += 1;
351	        }
352	        if (this.householdSize != null && this.householdSize >= 3) {
353	            points += 2;
