363	     * {@code 1} for 0-1 points, {@code 2} for 2-3 points, {@code 3} for 4-5 points, and {@code 4} for
364	     * 6 or more points.
365	     *
366	     * <p>When a {@link #getMembershipLevelCap() membershipLevelCap} is present the result is capped to
367	     * it, so a new owner's level cannot exceed one above the current maximum membershipLevel among
368	     * their household members. With no household member the cap is absent and the mapped level stands.
369	     */
370	    public Integer getMembershipLevel() {
371	        int points = getMembershipPoints();
372	        int level;
373	        if (points <= 1) {
374	            level = 1;
375	        }
376	        else if (points <= 3) {
377	            level = 2;
378	        }
379	        else if (points <= 5) {
380	            level = 3;
381	        }
382	        else {
383	            level = 4;
384	        }
385	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
386	            return this.membershipLevelCap;
387	        }
388	        return level;
389	    }
