392	     * The fiscal year containing {@code date}: fiscal years start on 1 July and are named for the
393	     * calendar year in which they end, so 1 July 2026 – 30 June 2027 is fiscal year {@code 2027}.
394	     */
395	    public static int fiscalYear(LocalDate date) {
396	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
397	    }
