399	    /**
400	     * The owner's fiscal year, derived at response time from the business-day-adjusted
401	     * {@link #registrationDate} (stamped business-day-adjusted at creation) as {@code FY<YY>},
402	     * where the fiscal year starts on 1 July and {@code YY} is the last two digits of the fiscal
403	     * year (the calendar year in which it ends). {@code null} when the registration date is absent.
404	     * Not persisted.
405	     */
406	    public String getFiscalYear() {
407	        if (this.registrationDate == null) {
408	            return null;
409	        }
410	        return String.format(Locale.ROOT, "FY%02d", fiscalYear(this.registrationDate) % 100);
411	    }
412	
413	    /**
414	     * The owner's tenure in elapsed fiscal years, measured from the {@link #registrationDate}'s
415	     * fiscal year to the current fiscal year (fiscal years start on 1 July); zero when the
416	     * registration date is absent or falls in a later fiscal year than today.
417	     */
418	    private long getTenureFiscalYears() {
419	        if (this.registrationDate == null) {
420	            return 0;
421	        }
422	        long years = (long) fiscalYear(LocalDate.now()) - fiscalYear(this.registrationDate);
423	        return Math.max(years, 0);
424	    }
425	
426	    /** Fixed city-to-region table used to derive {@link #getLocality()}. */
427	    private static final Map<String, String> CITY_REGION = Map.of(
428	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
429	
430	    /** Region -> inclusive 4-digit postcode range {low, high} used to derive {@link #getLocality()}. */
431	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
432	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
433	
434	    /** Fixed region-to-IANA-timezone table used to derive {@link #getTimezone()}. */
435	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
436	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
437	
438	    /**
439	     * The fixed city-to-region mapping ({@code Sydney -> NSW}, {@code Melbourne -> VIC},
440	     * {@code Brisbane -> QLD}): the region for {@code city}, or {@code null} when the city is not in
441	     * the table. Used only by postcode validation, which branches on "known region or not" by testing
442	     * for {@code null} before range-checking the postcode.
443	     */
444	    public static String regionOf(String city) {
445	        return CITY_REGION.get(city);
446	    }
447	
448	    /**
449	     * The region whose fixed postcode range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
450	     * {@code QLD 4000-4099}) contains {@code postcode}, or {@code null} when {@code postcode} is
451	     * absent, not a 4-digit number, or in no known range.
452	     */
453	    public static String regionOfPostcode(String postcode) {
454	        if (postcode == null || postcode.isEmpty()) {
455	            return null;
456	        }
457	        int value;
458	        try {
459	            value = Integer.parseInt(postcode);
460	        } catch (NumberFormatException ex) {
461	            return null;
462	        }
463	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
464	            int[] range = entry.getValue();
465	            if (value >= range[0] && value <= range[1]) {
466	                return entry.getKey();
467	            }
468	        }
469	        return null;
470	    }
471	
472	    /**
473	     * The owner's region, derived at response time from the {@code REGION} prefix of the
474	     * {@link #customerCode} (the segment before the first {@code '-'}). Because the customer code is
475	     * assigned as {@code <REGION>-<HASH8>} with REGION taken from the postcode, the locality follows
476	     * the same region-and-hash identity as the customer code. {@code UNKNOWN} when the owner has no
477	     * customer code.
478	     */
479	    public String getLocality() {
480	        if (this.customerCode == null) {
481	            return "UNKNOWN";
482	        }
483	        int dash = this.customerCode.indexOf('-');
484	        return dash < 0 ? this.customerCode : this.customerCode.substring(0, dash);
485	    }
486	
487	    /**
488	     * The owner's IANA timezone name, derived at response time from the {@link #getLocality()
489	     * locality}/region via the fixed region-to-timezone table ({@code NSW -> Australia/Sydney},
